// Public educational content and ephemeral practice state only. No account mutations.
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const COACH_SOURCE='https://www.sebi.gov.in/sebi_data/attachdocs/jun-2026/1780397706130.pdf';
export const COACH_STEPS=['Your route','Understand fields','Practise safely','Prepare','After submission','Get unstuck'];
export const FIELD_GUIDE=[
 {title:'Account or folio reference',meaning:'Identifies the account whose nomination you want to record or change.',why:'Helps the institution apply the request to the correct record.',where:'Use your own statement or authenticated institution portal.',check:'Follow the official form’s format. Never enter the reference in this practice guide.'},
 {title:'Nominee name and relationship',meaning:'Names the person you wish to nominate and their relationship to you.',why:'These are mandatory nominee particulars under the cited securities framework.',where:'Confirm the correct particulars with the nominee before using the official form.',check:'Use accurate particulars, not a nickname. Nomination is not a substitute for resolving inheritance or ownership questions.'},
 {title:'Date of birth when the nominee is a minor',meaning:'Records the minor nominee’s date of birth.',why:'Date of birth is mandatory when the nominee is a minor.',where:'Check a reliable record with the nominee’s parent or guardian.',check:'Use the date format requested by the official form; ask the institution if uncertain.'},
 {title:'Additional nominee particulars',meaning:'Contact details, share, identifier and guardian details appear in the model form.',why:'These particulars are optional under the cited framework; they can support communication or processing.',where:'Read the institution’s current form and its instructions before choosing what to provide.',check:'Do not invent missing information. Ask the institution to explain any field it labels mandatory that differs from this framework.'},
 {title:'Nomination visibility on statements',meaning:'The framework allows names or a Yes/No nomination-status indication on statements.',why:'This affects the personal information visible on the statement.',where:'Find this choice in the institution’s current nomination instructions.',check:'Choose deliberately. A Yes/No status alone does not show that the nominee particulars are correct.'},
 {title:'Holder consent and signatures',meaning:'Joint holders must agree to the nomination; the official channel records the required consent.',why:'The request needs the consent of all joint holders.',where:'Use only the institution’s official form or authenticated workflow.',check:'Do not sign a practice sheet or share an OTP here. Ask the institution which signatures or authentication steps apply.'}
];
export const STUCK_GUIDE={
 field:['I do not understand a field','Identify the field label and ask the institution what it requires for your account. Use the field guide for background; do not guess or invent a value.'],
 missing:['I do not have the information','Check whether the field is required for your situation. Obtain accurate information through a trusted route or ask the institution how to proceed. Do not submit fabricated details.'],
 rejected:['My request was rejected','Ask for the reason and the exact correction required in writing. Retain the response privately and use the institution’s official correction process. A rejected request does not confirm registration.'],
 waiting:['I have not received a response','Use your acknowledgement to ask the institution for the current status and its stated service timeline. Keep a record of that contact. Do not assume submission completed the change.'],
 wrong:['The recorded details are incorrect','Compare the confirmation with your intended particulars privately. Ask the institution for its correction or replacement process and check the resulting record again.'],
 complaint:['I need to complain','First raise the issue with the institution through its official complaint channel. Keep the facts, dates, requested resolution and response privately. If unresolved, check the relevant regulator’s official eligibility and escalation process; banking and securities routes differ.']
};
export const PRACTICE_FIELDS=[
 {id:'name',label:'Nominee name',choices:[['tara','Tara Rao'],['asha','Asha Rao'],['nickname','Little star']],correct:'tara',right:'Correct. Tara is the nominee; Asha is the account holder. Use accurate particulars rather than a nickname.',wrong:'Recheck who is being nominated. This field needs Tara’s accurate name, not the holder’s name or a nickname.'},
 {id:'relationship',label:'Relationship to the account holder',choices:[['daughter','Daughter'],['mother','Mother'],['broker','Broker']],correct:'daughter',right:'Correct. Tara is Asha’s daughter. Read the form’s relationship direction carefully.',wrong:'Read the relationship from the account holder’s perspective: Tara is Asha’s daughter.'},
 {id:'dob',label:'Minor nominee’s date of birth (DD/MM/YYYY)',choices:[['birth','14/06/2015'],['today','04/10/2026'],['omit','Leave blank because it is always optional']],correct:'birth',right:'Correct. The fictional birth date is 14 June 2015. Date of birth is required for a minor nominee under this securities framework.',wrong:'Use the nominee’s actual birth date in the requested format. Today’s date is not the birth date; this field is required for a minor nominee under the securities framework.'}
];
export function coachRoute(a={}){
 if(a.holderDeceased===true||a.deceased===true)return 'deceased';
 if(a.type==='bank')return 'bank';
 if(a.type==='mf'&&a.mfMode==='demat')return 'demat-linked';
 if(a.type==='mf'&&a.mfMode!=='folio')return 'unknown';
 return ['demat','mf'].includes(a.type)?'securities':'unknown';
}
const button=(action,value,label,extra='')=>`<button type="button" class="secondary" data-coach-action="${action}" data-coach-value="${esc(value)}" ${extra}>${esc(label)}</button>`;
const list=items=>`<ul>${items.map(s=>`<li>${esc(s)}</li>`).join('')}</ul>`;
export function createNominationCoach(){
 let rehearsal={},step=0,practice='',outcome='',stuck='',checks=new Set(),deceased=false;
 function reset(){rehearsal={};step=0;practice='';outcome='';stuck='';checks=new Set();deceased=false;}
 function handle(target){
  const el=target?.closest?.('[data-coach-action]');if(!el)return false;
  const {coachAction:action,coachValue:value}=el.dataset;
  if(action==='step'&&/^\d$/.test(value)&&Number(value)<COACH_STEPS.length)step=Number(value);
  else if(action==='practice'&&['name','otp','return'].includes(value))practice=value;
  else if(action.startsWith('practice-')&&PRACTICE_FIELDS.some(f=>f.id===action.slice(9)&&f.choices.some(([id])=>id===value)))rehearsal[action.slice(9)]=value;
  else if(action==='outcome'&&['done','wait','failed'].includes(value))outcome=value;
  else if(action==='stuck'&&Object.hasOwn(STUCK_GUIDE,value))stuck=value;
  else if(action==='check'&&['route','form','people','channel'].includes(value)){checks.has(value)?checks.delete(value):checks.add(value);}
  else if(action==='deceased')deceased=!deceased;
  else return false;
  return true;
 }
 function render(a={}){
  const route=deceased?'deceased':coachRoute(a),securities=route==='securities';
  const routeText={securities:a.type==='demat'?'Use the nomination route for your demat account through its depository participant (DP).':'Use the route for this mutual-fund folio through the AMC or its registrar and transfer agent (RTA).',bank:'Bank deposits use banking rules and the bank’s own process. The securities field guide does not apply. Ask the bank for the current nomination form for your deposit and holding type.','demat-linked':'These mutual-fund units are held in demat. Follow the linked demat account’s nomination route through its DP. Confirm the holding arrangement before using a folio form.',unknown:'Confirm the account type and whether fund units are held in a folio or demat before choosing a form.',deceased:'Stop the new-nomination journey. Contact the institution’s deceased-holder claim or transmission team. Required documents depend on the account and circumstances; this guide cannot decide entitlement.'}[route];
  let body='';
  if(route==='deceased')body=`<h3>Ask for the claim or transmission process</h3><p>${routeText}</p>`;
  else if(step===0)body=`<h3>Know the route before choosing a form</h3><p>${routeText}</p>${a.holding==='joint'?'<p>Joint holding: ask the institution how all holders provide consent through its supported channel.</p>':a.holding!=='sole'?'<p>Confirm whether the account is held solely or jointly before preparing a request.</p>':''}<ol><li>Check the existing nomination privately with the institution.</li><li>Find the current official form or authenticated online route.</li><li>Prepare accurate particulars and required consent.</li><li>Submit through the institution and keep its acknowledgement privately.</li><li>Check the resulting nomination record and any requested corrections.</li></ol><details><summary>Who does what?</summary><p>A depository holds securities electronically. A depository participant (DP) provides your account interface to it. An asset management company (AMC) manages a mutual fund. A registrar and transfer agent (RTA) services records and transactions for the fund. A broker facilitates trading; confirm which entity services your demat account.</p></details>`;
  else if(step===1)body=securities?`<h3>Read each field with a purpose</h3><p>This explains the securities framework, not a provider’s exact screen. Use the current official form. Source: sections 6, 7, 9.3 and 10.1; Annexure A, pages 6–7.</p>${FIELD_GUIDE.map(f=>`<details><summary>${esc(f.title)}</summary><dl><dt>What it means</dt><dd>${esc(f.meaning)}</dd><dt>Why it matters</dt><dd>${esc(f.why)}</dd><dt>Where to find it</dt><dd>${esc(f.where)}</dd><dt>Check carefully</dt><dd>${esc(f.check)}</dd></dl></details>`).join('')}`:`<h3>Choose the right form first</h3><p>${routeText}</p><p>Ask the institution to explain the account reference, nominee particulars, applicable minor-nominee requirements, consent and submission instructions on its current form. No securities-specific field requirements are applied here.</p>`;
  else if(step===2){
   const correct=PRACTICE_FIELDS.filter(f=>rehearsal[f.id]===f.correct).length;
   const fields=securities?`<div class="coach-rehearsal"><h4>Fictional form rehearsal</h4><p>Fictional account holder <strong>Asha Rao</strong> wants to nominate her daughter <strong>Tara Rao</strong>, born <strong>14 June 2015</strong>. For this exercise, the date is 4 October 2026, so Tara is a minor. Select the matching particulars below. These are invented people and a teaching example, not an official form.</p>${PRACTICE_FIELDS.map(f=>`<fieldset><legend>${esc(f.label)}</legend><div class="coach-options">${f.choices.map(([id,label])=>button('practice-'+f.id,id,label,`aria-pressed="${rehearsal[f.id]===id}"`)).join('')}</div>${rehearsal[f.id]?`<p class="coach-feedback" role="status">${esc(rehearsal[f.id]===f.correct?f.right:f.wrong)}</p>`:'<p>Choose an answer to check your understanding.</p>'}</fieldset>`).join('')}<p class="coach-feedback" role="status">${correct} of 3 fictional fields understood. ${correct===3?'Practice complete. You matched this fictional example; this is not an official submission, a check of your own form, or confirmation of registration.':'Complete or correct the remaining choices to finish this exercise. No readiness or registration is inferred from missing or incorrect answers.'}</p></div>`:'<p>The securities form rehearsal is available only after identifying a demat account or mutual-fund folio route. Use the institution’s own form for your account.</p>';
   body=`<h3>Practise with fictional information</h3><p>This is an illustrative exercise, not an official form. Fictional account holder Asha is reading a nomination form. It asks for a nominee’s name. Which information belongs in that field?</p><div class="coach-options">${button('practice','name','The intended nominee’s accurate name')}${button('practice','otp','An OTP received on the phone')}${button('practice','return','An expected investment return')}</div>${practice?`<p class="coach-feedback" role="status">${practice==='name'?'Correct. A nominee-name field identifies the nominee. Use accurate particulars in the institution’s official form.':'Try again. The field asks who is being nominated. An OTP is an authentication secret; an investment return is unrelated to this field.'}</p>`:''}${fields}<p>No real names, identifiers, signatures or documents are requested. This exercise never changes your account’s status.</p>`;
  }
  else if(step===3)body=`<h3>Prepare outside Virasat</h3><p>${routeText}</p><p>These temporary ticks are reminders, not validation that your form is correct.</p>${[['route','I know which institution and account route apply.'],['form','I have checked the current official form and its instructions.'],['people','I can obtain accurate particulars and any required holder consent privately.'],['channel','I know the official submission channel and how to retain an acknowledgement.']].map(([id,label])=>`<label class="coach-check"><input type="checkbox" data-coach-action="check" data-coach-value="${id}" ${checks.has(id)?'checked':''}> <span>${label}</span></label>`).join('')}<p>${checks.size} of 4 preparation reminders checked. This does not submit or confirm a nomination.</p>`;
  else if(step===4)body=`<h3>Know what the response proves</h3>${list(['An acknowledgement proves receipt of a request; it does not by itself prove registration.','A correction or rejection means you need to follow up through the official process.','An institutional confirmation may show status only. Inspect nominee particulars privately when available before saying those particulars were checked.'])}<p>Practice: Asha receives “Your request has been received.” What should she conclude?</p><div class="coach-options">${button('outcome','done','The nomination is registered')}${button('outcome','wait','The request was received; check the outcome')}${button('outcome','failed','The request was rejected')}</div>${outcome?`<p class="coach-feedback" role="status">${outcome==='wait'?'Correct. Keep the acknowledgement privately and check the institution’s outcome. This practice answer does not confirm your real account.':'That message confirms receipt only. It does not establish registration or rejection. Check the institution’s outcome.'}</p>`:''}`;
  else body=`<h3>Find a useful next step</h3><div class="coach-options">${Object.entries(STUCK_GUIDE).map(([key,[label]])=>button('stuck',key,label,`aria-pressed="${stuck===key}"`)).join('')}</div>${stuck?`<div class="coach-feedback" role="status"><h4>${esc(STUCK_GUIDE[stuck][0])}</h4><p>${esc(STUCK_GUIDE[stuck][1])}</p><p>Useful question: “What exact action is still needed, what evidence should I retain, and how will I know the request has been resolved?”</p></div>`:''}`;
  return `<section class="nomination-coach" lang="en" aria-labelledby="coach-title"><h1 id="coach-title">Learn the nomination journey</h1><p class="coach-preview">English text-only preview. This new guide is not yet translated or included in recorded audio.</p><p>Learning only: no submission, institutional verification or investment recommendation. Practice choices and checkmarks stay in memory for this visit; they are not saved.</p>${button('deceased','',deceased?'Return to learning guide':'Is an account holder deceased?',`aria-pressed="${deceased}"`)}${route!=='deceased'?`<nav aria-label="Nomination learning steps" class="coach-nav">${COACH_STEPS.map((label,i)=>button('step',i,`${i+1}. ${label}`,i===step?'aria-current="step"':'')).join('')}</nav>`:''}<div class="coach-content" tabindex="-1">${body}</div>${route!=='deceased'?`<div class="coach-navigation">${step?button('step',step-1,'Previous step'):''}${step<5?button('step',step+1,'Next step'):''}</div>`:''}<details class="coach-source"><summary>Sources and limits</summary><p>Securities learning source: <a href="${COACH_SOURCE}" target="_blank" rel="noopener noreferrer">SEBI circular of 29 May 2026</a>, sections 6, 7, 9.3, 10.1 and Annexure A (pages 6–7). Content reviewed 4 October 2026. This review does not verify any institution’s current screen or processing timeline.</p><p>Banking requirements are separate. Always use the institution’s current official instructions. Virasat does not determine legal ownership, inheritance, claim eligibility or investment suitability. Never share passwords, PINs or OTPs with a helper.</p></details></section>`;
 }
 return {render,handle,reset};
}
